style.css:
@-moz-document domain("roblox.com") {
body {
    background: url("https://tr.rbxcdn.com/14007225805/420/420/Image/Png") no-repeat center center fixed;
    background-size: cover;
  }

  .navbar, .game-card-container, .content {
    background-color: rgba(255, 255, 255, 0.8) !important;
    border-radius: 10px;
  }

  .btn-primary {
    background-color: #d71a28 !important; /* Red from the flag */
    border-color: #007a33 !important;     /* Cedar green */
  }

  .btn-primary:hover {
    background-color: #007a33 !important;
    border-color: #d71a28 !important;
  }
}
